import {finishes,accessories,compatibility,productSvg} from './catalog-data.js';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');
export function combinationCard(p,{width=p.kind==='door'&&p.widths.includes(24)?24:p.widths[0],finish='natural-oak',style='Shaker',storage='',forceStorage=false}={}){
 const preferred={door:'waste',wide:'wide-rollout',pantry:'pantry',wall:'wall-shelf-riser','tall-wall':'wall-tray-dividers','corner-wall':'wall-corner-turntable',utility:'utility-caddies'}[p.kind];const matches=accessories.filter(a=>compatibility(p,width,a).ok).sort((a,b)=>Number(b.id===preferred)-Number(a.id===preferred));const a=matches.find(a=>a.id===storage)||(forceStorage?null:matches[0]);const f=finishes.find(f=>f.id===finish)||finishes[0];const params=new URLSearchParams({product:p.id,width:String(width),finish:f.id,style});if(a&&(storage||forceStorage))params.set('storage',a.id);
 return `<div class="combo-visual"><div class="combo-cabinet"><span class="combo-image-label">Cabinet exterior</span>${productSvg(p,{width,style,finish:f.id})}</div><div class="combo-interior"><span class="combo-image-label">${a?'Inside inspiration':'Interior to plan'}</span>${a?`<img src="/kabbyhome/assets/${a.image}" alt="${esc(a.name)} reference showing ${esc(a.purpose.toLowerCase())}" loading="lazy"><span class="combo-photo-label">Accessory reference</span>`:`<div class="combo-empty-art">${productSvg(p,{width,style,finish:f.id})}<span>Plan the interior with us</span></div>`}</div></div><div class="combo-copy"><span class="eyebrow">${p.category} cabinet · ${esc(f.name)} · ${style}</span><h2>${esc(p.name)}</h2><p class="combo-purpose">${a?esc(a.purpose):esc(p.description)}</p>${a?.fitNote?`<p class="caption">${esc(a.fitNote)}</p>`:''}${a?.photoSource?`<a class="caption" href="${esc(a.photoSource)}" target="_blank" rel="noopener">Photo: ${esc(a.photoCredit)} ↗</a>`:''}<div class="combo-price"><strong>Quote required</strong><small>${width}″ wide · Shaker / Slab</small></div><details class="combo-options" ${['wall','tall-wall','corner-wall','utility'].includes(p.kind)?'open':''}><summary>See accessory add-ons & widths</summary><fieldset class="combo-widths"><legend>Choose a width</legend><div>${p.widths.map(w=>`<button type="button" data-combo-width="${w}" ${forceStorage&&a&&!compatibility(p,w,a).ok?'disabled title="This width does not fit the selected storage option"':''} aria-label="${p.name}: ${w} inch width" aria-pressed="${w===width}">${w}″</button>`).join('')}</div></fieldset><fieldset class="combo-accessories"><legend>Explore what fits inside</legend><div>${matches.length?matches.map(item=>`<button type="button" data-combo-storage="${item.id}" aria-pressed="${a?.id===item.id}">${esc(item.name)}</button>`).join(''):'<p class="caption">No accessory match in this planning range. Ask us to review your storage needs.</p>'}</div></fieldset><div class="combo-fit-note">${a?`<strong>${esc(a.name)}</strong><span>Planning match for this ${width}″ ${p.name.toLowerCase()}. Exact internal clearance and hardware need confirmation.</span>`:'<span>Interior options and exact fit can be reviewed with your cabinet specification.</span>'}</div></details><div class="combo-card-footer"><a class="btn" href="/kabbyhome/start-order/?${params}">Customize Cabinet →</a><a class="textlink" href="/kabbyhome/cabinets/${p.id}/">View Specifications</a></div><details class="combo-specs"><summary>Dimensions & material options</summary><p>${width}″ W × ${p.depths.join(' / ')}″ D × ${p.heights.join(' / ')}″ cabinet-box H. ${esc(f.doorMaterials.join(' or '))}. Box construction chosen separately. Final size, materials, fit and price require specification review.</p></details></div>`;
}
